import java.util.ArrayList;

public class AutoboxDemo {
    public static void main(String[] args) {

        // Autoboxing — int to Integer
        Integer x = 5;          // compiler: Integer.valueOf(5)
        Integer y = 100;        // compiler: Integer.valueOf(100)

        // Unboxing — Integer to int
        int sum = x + y;        // compiler: x.intValue() + y.intValue()
        System.out.println(sum); // 105

        // Collections require objects — autoboxing happens on every add
        ArrayList<Integer> list = new ArrayList<>();
        list.add(42);   // autoboxed: Integer.valueOf(42)
        list.add(99);   // autoboxed: Integer.valueOf(99)
        int first = list.get(0); // unboxed: .intValue()

        // NullPointerException trap during unboxing
        Integer n = null;
        // int value = n;  // NullPointerException — cannot unbox null
        // n.intValue() is called implicitly — null has no .intValue()

        // Safe unboxing — always null-check first
        if (n != null) {
            int value = n;  // safe
        }
    }
}
