import java.util.HashMap;

public class AutoboxNPE {

    static Integer getScore(boolean found) {
        return found ? 95 : null;  // returns null when not found
    }

    public static void main(String[] args) {

        // Case 1: method returns Integer, assigned to int
        int score = getScore(false); // NPE — compiler: getScore(false).intValue() → null.intValue()

        // Case 2: HashMap.get() returns null for absent key
        HashMap<String, Integer> map = new HashMap<>();
        map.put("Alice", 90);
        int bobScore = map.get("Bob"); // NPE — Bob not in map, get() returns null

        // Safe fix: use getOrDefault
        int bobSafe = map.getOrDefault("Bob", 0); // 0 — no NPE

        // Case 3: arithmetic with null wrapper
        Integer a = null;
        // int sum = a + 5; // NPE — compiler: a.intValue() + 5 → null.intValue()

        // Case 4: switch on null Integer
        Integer x = null;
        // switch (x) { ... }  // NPE — switch unboxes x first

        // Safe pattern: always null-check before unboxing
        Integer n = getScore(false);
        int value = (n != null) ? n : 0;  // null-safe

        // Or use Objects.requireNonNullElse
        int safe = java.util.Objects.requireNonNullElse(n, 0); // Java 9+
    }
}
