public class IntegerCacheDemo {
    public static void main(String[] args) {

        // Values in cache range (-128 to 127)
        Integer a = 127;  // Integer.valueOf(127) — returns cached object
        Integer b = 127;  // Integer.valueOf(127) — returns SAME cached object
        System.out.println(a == b);     // true  — same object
        System.out.println(a.equals(b)); // true  — same value

        // Values outside cache range
        Integer c = 128;  // Integer.valueOf(128) — creates new object
        Integer d = 128;  // Integer.valueOf(128) — creates DIFFERENT new object
        System.out.println(c == d);     // false — different objects!
        System.out.println(c.equals(d)); // true  — same value

        // The boundary in action — 127 works, 128 doesn't
        Integer x = 127;
        Integer y = 127;
        Integer p = 128;
        Integer q = 128;
        System.out.println(x == y); // true
        System.out.println(p == q); // false — same code, different result!

        // Rule: always use .equals() for Integer comparison
        System.out.println(p.equals(q)); // true — correct
    }
}
